import Foundation

// Port of src/utils/clauseSkeleton.js — the "Struttura" reading aid for
// hypotactic prose. Classifies each token of a sentence as a conjugated verb
// (`finite`), the participle half of a two-word verb (`compound`), a bare
// participle that works as a shortened relative clause (`participle`), or
// `plain`, and marks comma-delimited asides (`dim`).
//
// The word lists below are copied verbatim from the JS module, and the logic
// follows it function for function. The ClauseSkeleton fixture (generated by
// running the real JS over every passage verse and vocab example) proves the
// two agree token for token, so when a list changes on the web, change it here
// and regenerate the fixtures. The design notes — why each context rule
// exists and what it used to get wrong — live in the JS file.

public enum ClauseRole: String, Codable, Sendable {
    case plain, finite, compound, participle
}

public struct SkeletonToken: Equatable, Sendable {
    public let text: String
    public let isWord: Bool
    public internal(set) var role: ClauseRole
    public internal(set) var dim: Bool

    public init(text: String, isWord: Bool, role: ClauseRole, dim: Bool) {
        self.text = text
        self.isWord = isWord
        self.role = role
        self.dim = dim
    }
}

public struct ClauseAnalysis: Equatable, Sendable {
    public let tokens: [SkeletonToken]
    /// The number of conjugated verbs — the clause count the reader is taught
    /// to look for first.
    public let finiteCount: Int
    public let hasParenthetical: Bool
}

