// ── elision and clitics ──────────────────────────────────────────────────────

// JS: /^([a-zà-ÿ]{1,4})['’](.+)$/ on the lowercased word.
private func isElisionPrefixChar(_ c: Character) -> Bool {
    guard c.unicodeScalars.count == 1, let v = c.unicodeScalars.first?.value else { return false }
    return (0x61...0x7A).contains(v) || (0xE0...0xFF).contains(v)
}

private func elisionSplit(_ word: String) -> String? {
    let chars = Array(word.lowercased())
    guard let apo = chars.firstIndex(where: { $0 == "'" || $0 == "’" }),
          (1...4).contains(apo),
          chars[..<apo].allSatisfy(isElisionPrefixChar),
          apo + 1 < chars.count
    else { return nil }
    return String(chars[(apo + 1)...])
}

public func stripElision(_ word: String) -> String {
    elisionSplit(word) ?? word.lowercased()
}

public func hasElision(_ word: String) -> Bool {
    elisionSplit(word) != nil
}

// JS: /(?:gli|lo|la|li|le|ne|mi|ti|ci|vi|si)$/ — "gli" is tried first.
private let twoLetterEnclitics = ["lo", "la", "li", "le", "ne", "mi", "ti", "ci", "vi", "si"]

private func encliticLength(_ w: String) -> Int? {
    if w.hasSuffix("gli") { return 3 }
    return twoLetterEnclitics.contains(where: { w.hasSuffix($0) }) ? 2 : nil
}

public func stripClitics(_ word: String) -> String {
    var w = stripElision(word)
    for _ in 0..<2 {
        guard let n = encliticLength(w) else { break }
        let stem = String(w.dropLast(n))
        if stem.count < 4 { break }
        w = stem
    }
    return w
}

private func endsWith(_ w: String, _ suffixes: [String]) -> Bool {
    suffixes.contains(where: { w.hasSuffix($0) })
}

// ── auxiliaries ──────────────────────────────────────────────────────────────

public func isAuxiliary(_ word: String) -> Bool {
    let w = stripElision(word)
    return aux.contains(w) || nonfiniteAux.contains(w) || nonfiniteAux.contains(stripClitics(w))
}

// ── finite verbs ─────────────────────────────────────────────────────────────

private let imperfettoEndings: [String] = ["av", "ev", "iv"].flatMap { stem in
    ["o", "i", "a", "amo", "ate", "ano"].map { stem + $0 }
}
private let futureEndings: [String] = [
    "ò", "ai", "à", "emo", "ete", "anno", "ei", "esti", "ebbe", "emmo", "este", "ebbero",
].map { "r" + $0 }

// JS FINITE_SUFFIXES, as [suffixes, minimum length].
private let finiteSuffixes: [([String], Int)] = [
    (imperfettoEndings, 5),                          // imperfetto
    (futureEndings, 5),                              // futuro / condizionale
    (["ò", "ì"], 3),                                 // passato remoto 3sg
    (["ai"], 5),                                     // passato remoto 1sg
    (["arono", "erono", "irono", "ettero"], 6),      // passato remoto 3pl
    (["ssero", "ssimo"], 6),                         // congiuntivo / pass. rem. pl
    (["asse", "esse", "isse"], 5),                   // congiuntivo imperfetto sg
    (["iamo"], 5),                                   // 1a plurale
    (["ate", "ite", "ete"], 5),                      // 2a plurale / imperativo
    (["ano", "ono"], 5),                             // 3a plurale presente
]

public func isFiniteVerb(_ word: String) -> Bool {
    let w = stripElision(word)
    if w.isEmpty || notFinite.contains(w) { return false }
    if finiteLexicon.contains(w) { return true }
    if finiteSuffixes.contains(where: { w.count >= $0.1 && endsWith(w, $0.0) }) { return true }
    // An imperative that swallowed its pronoun ("lodàtelo"): only the lexicon
    // and the imperative endings may apply to the stripped stem.
    let stem = stripClitics(w)
    if stem == w || notFinite.contains(stem) { return false }
    return finiteLexicon.contains(stem)
        || (stem.count >= 5 && endsWith(stem, ["iamo", "ate", "ite", "ete"]))
}

// ── participles, gerunds, infinitives ────────────────────────────────────────

// JS: /(?:(?:at|ut)[oai]|it[oa])$/
private let participleEndings = ["ato", "ati", "ata", "uto", "uti", "uta", "ito", "ita"]

public func isParticiple(_ word: String) -> Bool {
    let w = stripElision(word)
    if w.isEmpty || hasElision(word) || notParticiple.contains(w) { return false }
    if participleLexicon.contains(w) { return true }
    return w.count >= 5 && endsWith(w, participleEndings)
}

public func isGerund(_ word: String) -> Bool {
    let w = stripClitics(stripElision(word))
    return w.count >= 6 && endsWith(w, ["ando", "endo"]) && !notGerund.contains(w)
}

public func isInfinitive(_ word: String) -> Bool {
    let w = stripElision(word)
    if hasElision(word) { return false }
    if w.count < 4 || notInfinitive.contains(w) { return false }
    return endsWith(w, ["are", "ere", "ire", "arsi", "ersi", "irsi"])
}

public func isDeterminer(_ word: String) -> Bool {
    determiners.contains(stripElision(word))
}

// ── analysis ─────────────────────────────────────────────────────────────────

private let auxLookback = 2
private let sentenceStops: Set<Character> = [".", ";", ":", "!", "?", "…", "»", "«", "\""]
private let feminineParticipleEndings = ["ate", "ute", "ite"]

private struct Segment {
    let start: Int
    let end: Int
    let closedLeft: Bool
    let closedRight: Bool
    var wordIndices: [Int] = []
    var head: String = ""
}

/// Analyze one sentence — see `analyze()` in clauseSkeleton.js.
public func analyzeClauses(_ text: String) -> ClauseAnalysis {
    var tokens = tokenize(text).map {
        SkeletonToken(text: $0.text, isWord: $0.isWord, role: .plain, dim: false)
    }
    let wordIdx = tokens.indices.filter { tokens[$0].isWord }

    // The word before word n, only when nothing but whitespace separates them.
    func prevWord(_ n: Int) -> String {
        guard n > 0 else { return "" }
        let gap = tokens[(wordIdx[n - 1] + 1)..<wordIdx[n]].map(\.text).joined()
        return gap.allSatisfy(\.isWhitespace) ? stripElision(tokens[wordIdx[n - 1]].text) : ""
    }
    // A possessive only determines what follows when it is prenominal.
    func afterDeterminerAt(_ n: Int) -> Bool {
        let prev = prevWord(n)
        guard determiners.contains(prev) else { return false }
        guard possessives.contains(prev) else { return true }
        let before = prevWord(n - 1)
        return before.isEmpty || determiners.contains(before)
            || prepositions.contains(before) || cliticOrArticle.contains(before)
    }
    func leansOnAux(_ n: Int) -> Bool {
        wordIdx[max(0, n - auxLookback)..<n].contains { isAuxiliary(tokens[$0].text) }
    }

    // Pass 1 — conjugated verbs, in context.
    for (n, i) in wordIdx.enumerated() {
        let prev = prevWord(n)
        let afterDeterminer = afterDeterminerAt(n)
        let afterArticleOrClitic = afterDeterminer || cliticOrArticle.contains(prev)
        let w = stripElision(tokens[i].text)

        guard isFiniteVerb(tokens[i].text) else { continue }
        if !neverNoun.contains(w) {
            if afterDeterminer { continue }
            if nounHomographVerbs.contains(w), afterArticleOrClitic || prenominal.contains(prev) { continue }
        }
        if isParticiple(tokens[i].text), leansOnAux(n) { continue }
        tokens[i].role = .finite
    }

    // Pass 1b — participles: compound after an auxiliary, bare otherwise.
    for (n, i) in wordIdx.enumerated() {
        if tokens[i].role == .finite { continue }
        let w = stripElision(tokens[i].text)
        let prev = prevWord(n)
        if leansOnAux(n) {
            if isParticiple(tokens[i].text)
                || (w.count >= 4 && endsWith(w, feminineParticipleEndings) && !hasElision(tokens[i].text))
                || (peccatoLike.contains(w) && avere.contains(prev)) {
                tokens[i].role = .compound
            }
            continue
        }
        guard isParticiple(tokens[i].text) else { continue }
        if afterDeterminerAt(n) || cliticOrArticle.contains(prev) || prenominal.contains(prev) { continue }
        if nounParticiples.contains(w) { continue }
        tokens[i].role = .participle
    }

    // Pass 2 — asides.
    var segments: [Segment] = []
    var start = 0
    var leftComma = false
    for (i, t) in tokens.enumerated() where !t.isWord {
        let stop = t.text.contains(where: { sentenceStops.contains($0) })
        let comma = t.text.contains(",")
        if !stop && !comma { continue }
        segments.append(Segment(start: start, end: i, closedLeft: leftComma, closedRight: !stop && comma))
        start = i + 1
        leftComma = !stop && comma
    }
    segments.append(Segment(start: start, end: tokens.count, closedLeft: leftComma, closedRight: false))

    for s in segments.indices {
        let seg = segments[s]
        let words = (seg.start..<seg.end).filter { tokens[$0].isWord }
        segments[s].wordIndices = words
        segments[s].head = words.first.map { stripElision(tokens[$0].text) } ?? ""
        // A lone feminine-plural participle between commas ("ma, entrate,").
        if seg.closedLeft, seg.closedRight, words.count == 1 {
            let only = words[0]
            if tokens[only].role == .finite, endsWith(stripElision(tokens[only].text), feminineParticipleEndings) {
                tokens[only].role = .participle
            }
        }
    }

    var hasParenthetical = false
    for s in segments.indices {
        let seg = segments[s]
        guard seg.closedLeft, seg.closedRight else { continue }
        let prev: Segment? = s > 0 ? segments[s - 1] : nil
        let next: Segment? = s + 1 < segments.count ? segments[s + 1] : nil
        guard isAsideSegment(seg, prev: prev, next: next, tokens: tokens) else { continue }
        hasParenthetical = true
        for j in seg.start..<seg.end { tokens[j].dim = true }
    }

    return ClauseAnalysis(
        tokens: tokens,
        finiteCount: tokens.filter { $0.role == .finite }.count,
        hasParenthetical: hasParenthetical
    )
}

private func isAsideSegment(_ seg: Segment, prev: Segment?, next: Segment?, tokens: [SkeletonToken]) -> Bool {
    let words = seg.wordIndices.map { tokens[$0] }
    if words.isEmpty { return false }
    if words.contains(where: { $0.role == .finite || $0.role == .compound }) { return false }
    let head = seg.head
    if coordinators.contains(head) || subordinators.contains(head) || proclitics.contains(head) { return false }
    if words.contains(where: { isInfinitive($0.text) }) { return false }

    // An implicit clause — gerund or bare participle — is an aside at any length.
    if words.contains(where: { $0.role == .participle || isGerund($0.text) }) { return true }

    if words.count > 6 { return false }
    if words.contains(where: { subordinators.contains(stripElision($0.text)) }) { return false }

    if prepositions.contains(head) {
        if prev?.head == head || next?.head == head { return false }
        if words.contains(where: { coordinators.contains(stripElision($0.text)) }) { return false }
        return true
    }

    if articles.contains(head) && words.count < 3 { return false }
    if words.count > 1 {
        guard let prev, let beforeIdx = prev.wordIndices.last else { return false }
        let tail = stripElision(tokens[beforeIdx].text)
        if coordinators.contains(tail) || prepositions.contains(tail) || timeAdverbs.contains(tail) { return false }
    }
    return true
}
